  "id": "http-sapcp:HttpRequestViaDestination:1",
  "catalog": "http-sapcp",
  "name": "HttpRequestViaDestination",
  "description": "Execute an HTTP request using an SAP Destination service destination for URL resolution and authentication.",
  "version": 1,
  "inputKeys": {
    "destinationName": {
      "type": "string",
      "description": "The name of an SAP BTP destination. The URL, authentication, and additional properties are resolved from the destination configuration.",
      "required": true
    },
    "destinationLevel": {
      "type": "string",
      "description": "The level at which the destination is configured. Use 'subaccount' for destinations created at the subaccount level, or 'instance' for destinations created at the service instance level.",
      "required": false,
      "defaultValue": "subaccount",
      "allowedValues": [
        "subaccount",
        "instance"
      ]
    },
    "serviceKey": {
      "type": "object",
      "description": "Service key for the SAP Destination service used to resolve the destination. Required only if the destination is in a different subaccount than the one where SAP Automation Pilot is provisioned.",
      "required": false,
      "sensitive": true,
      "defaultValue": null
    },
    "destinationServiceHeaders": {
      "type": "object",
      "description": "Additional headers to be included in the request to the Destination service when resolving the destination. This can be used, for example, to provide a custom 'x-user-token' for user identity propagation.",
      "required": false
    },
    "method": {
      "type": "string",
      "description": "The HTTP method to be used for the request. Examples: GET, POST, PUT, DELETE, PATCH",
      "required": true
    },
    "uri": {
      "type": "string",
      "description": "An optional path to append to the destination's base URL. If not provided, only the destination URL is used.",
      "required": false
    },
    "headers": {
      "type": "object",
      "description": "Additional request headers. These are merged with any headers resolved from the destination configuration.",
      "required": false
    },
    "body": {
      "type": "string",
      "description": "The payload of the HTTP request",
      "required": false
    },
    "timeout": {
      "type": "number",
      "description": "An optional execution timeout in seconds",
      "required": false,
      "minValue": 1,
      "maxValue": 90,
      "defaultValue": "3"
    },
    "succeedOnTimeout": {
      "type": "boolean",
      "description": "Prevents the command from failing in case of a timeout. If set to true, the response of the timed-out request will have body 'null', the response headers will be '{}', and the response status code will be '-1'.",
      "required": false,
      "defaultValue": "false"
    },
    "successResponseCodes": {
      "type": "array",
      "description": "The response codes which will be used to treat this HTTP request as successful. Example: [\"2xx\", \"3xx\", \"404\"]",
      "required": false,
      "defaultValue": "[\"2xx\"]"
    },
    "responseBodyTransformer": {
      "type": "string",
      "sensitive": false,
      "description": "A dynamic expression used to transform the response body string. If you need to use it as an object, it must be parsed, for example, using 'toObject'. The result replaces the original response body. Do not put the expression in the $() construct.",
      "required": false
    },
    "omitBodyInErrorMessage": {
      "type": "boolean",
      "sensitive": false,
      "description": "Whether the response body should be excluded from the error message when the HTTP request fails. Set this to true if you want to avoid sensitive data exposure.",
      "required": false,
      "defaultValue": "false"
    },
    "ignoreResponseBody": {
      "type": "boolean",
      "sensitive": false,
      "description": "When set to true, the response body is omitted from the command output. Use this to avoid execution size limit failures when the response body is not needed. This setting is independent of 'omitBodyInErrorMessage'.",
      "required": false,
      "defaultValue": "false"
    }
  },
  "outputKeys": {
    "body": {
      "type": "string",
      "description": "The response payload"
    },
    "headers": {
      "type": "object",
      "description": "The response headers"
    },
    "status": {
      "type": "number",
      "description": "The status code of the response. Examples: 200, 301, 404, 503. In case of no response or a timeout, the status codes may be 0 and -1."
    },
    "size": {
      "type": "number",
      "description": "The size of the response body in bytes. Example: 1048576"
    },
    "time": {
      "type": "number",
      "description": "The execution time of the request in milliseconds. Example: 321"
    },
    "url": {
      "type": "string",
      "description": "The target URL for the request"
    },
    "method": {
      "type": "string",
      "description": "The HTTP method used for the request"
    }
  }
}

