          "method": "GET",
          "authorizationHeader": "Bearer $(.execution.input.token)",
          "successResponseCodes": "[\"404\",\"200\",\"409\"]",
          "url": "$(.execution.input.githubServer | if startswith(\"https://\") then . else \"https://\" + . end | rtrimstr(\"/\") | if endswith(\"/api/v3\") then . else . + \"/api/v3\" end)/repos/$(.execution.input.owner | toUrlEncoded | split(\"+\") | join(\"%20\"))/$(.execution.input.repository | toUrlEncoded | split(\"+\") | join(\"%20\"))/git/trees/$((.execution.input.branch + \":\" + (.execution.input.path | split(\"/\")[:-1] | join(\"/\"))) | toUrlEncoded | split(\"+\") | join(\"%20\"))",
          "timeout": "5"
        },
