            {
              "semantic": "AND",
              "cases": [
                {
                  "expression": "$(.GetGitTree.output.body | toObject.type)",
                  "operator": "NOT_EQUALS",
                  "semantic": "OR",
                  "values": [
                    "tree"
                  ]
                }
              ]
            }
          ]
