                {
                  "semantic": "OR",
                  "cases": [
                    {
                      "expression": "$(.GetGitTree.output.body | toObject.type)",
                      "operator": "EQUALS",
                      "semantic": "OR",
                      "values": [
                        "tree"
                      ]
                    }
                  ]
