{
  "id": "http-sapcp:GetTokenViaRefreshToken:1",
  "name": "GetTokenViaRefreshToken",
  "description": "Obtain an access token via the OAuth 2.0 Refresh Token grant type",
  "catalog": "http-sapcp",
  "version": 1,
  "inputKeys": {
    "clientId": {
      "type": "string",
      "required": true,
      "description": "An OAuth 2.0 client ID used for authentication"
    },
    "tokenUrl": {
      "type": "string",
      "required": true,
      "description": "An OAuth 2.0 server token URL endpoint which supports the Refresh Token grant type"
    },
    "clientSecret": {
      "type": "string",
      "sensitive": true,
      "required": false,
      "description": "The client secret for the specified OAuth 2.0 client ID used for authentication"
    },
    "refreshToken": {
      "type": "string",
      "sensitive": false,
      "required": true,
      "description": "The refresh token used to obtain the new access token"
    }
  },
  "outputKeys": {
    "expiresIn": {
      "type": "number",
      "description": "The time validity of the access token in seconds"
    },
    "accessToken": {
      "type": "string",
      "sensitive": true,
      "description": "The obtained access token"
    },
    "tokenType": {
      "type": "string",
      "description": "The type of the obtained access token"
    },
    "refreshToken": {
      "type": "string",
      "sensitive": true,
      "description": "The obtained refresh token"
    }
  },
  "tags": {},
  "configuration": {
    "values": [],
    "output": {
      "expiresIn": "$(.nonSensitiveData.output.message | toObject.expires_in)",
      "accessToken": "$(.getToken.output.body | toObject.access_token)",
      "tokenType": "$(.nonSensitiveData.output.message | toObject.token_type)",
      "refreshToken": "$(.getToken.output.body | toObject.refresh_token)"
    },
    "executors": [
      {
        "execute": "http-sapcp:SensitiveHttpRequest:1",
        "input": {
          "headers": "{\"Content-Type\": \"application/x-www-form-urlencoded\"}",
          "password": "$(.execution.input.clientSecret)",
          "method": "POST",
          "body": "grant_type=refresh_token&refresh_token=$(.execution.input.refreshToken | toUrlEncoded)",
          "user": "$(.execution.input.clientId)",
          "url": "$(.execution.input.tokenUrl)",
          "timeout": "5"
        },
        "alias": "getToken",
        "initialDelay": null,
        "pause": null,
        "when": null,
        "validate": null,
        "autoRetry": {
          "maxCount": 3,
          "delay": "5s",
          "logic": "FIXED",
          "applyOnValidation": false,
          "when": {
            "semantic": "OR",
            "conditions": [
              {
                "semantic": "OR",
                "cases": [
                  {
                    "expression": "$([408, 429, 502, 503, 504] | filter(. == $.getToken.output.status) | length)",
                    "operator": "EQUALS",
                    "semantic": "OR",
                    "values": [
                      "1"
                    ]
                  }
                ]
              }
            ]
          }
        },
        "repeat": null
      },
      {
        "execute": "utils-sapcp:Void:1",
        "input": {
          "message": "$({ token_type: (.getToken.output.body | toObject.token_type), expires_in: (.getToken.output.body | toObject.expires_in) })"
        },
        "alias": "nonSensitiveData"
      }
    ]
  }
}

