{
  "id": "http-sapcp:HttpRequest:1",
  "catalog": "http-sapcp",
  "name": "HttpRequest",
  "description": "Execute an HTTP request. Supported authentication methods: Custom Authorization Header; OAuth 2.0 Client Credentials, Password, and Refresh Token Grant Flows; Basic Authentication; IAS Technical User Certificate Authentication; no authentication.",
  "version": 1,
  "inputKeys": {
    "url": {
      "type": "string",
      "description": "The target HTTP URL to be used for the request",
      "required": true
    },
    "method": {
      "type": "string",
      "description": "The HTTP method to be used for the request. Examples: GET, POST, PUT, DELETE, PATCH",
      "required": true
    },
    "user": {
      "type": "string",
      "description": "The name of a technical user or an OAuth 2.0 client ID used for authentication. Related input keys: 'password' or 'tokenUrl'",
      "required": false
    },
    "password": {
      "type": "string",
      "sensitive": true,
      "description": "The password for the specified technical user or the client secret for the specified OAuth 2.0 client ID used for authentication. Related input keys: 'user' or 'tokenUrl'",
      "required": false,
      "defaultValue": null
    },
    "tokenUrl": {
      "type": "string",
      "description": "An OAuth 2.0 server token URL endpoint which supports the chosen OAuth flow. If the 'tokenUrl' key is not provided, Basic authentication will be used (see 'user' and 'password').",
      "required": false
    },
    "clientId": {
      "type": "string",
      "description": "An OAuth 2.0 client ID used for authentication. Related input keys: 'clientSecret', 'tokenUrl'",
      "required": false
    },
    "clientSecret": {
      "type": "string",
      "sensitive": true,
      "description": "The client secret for the specified OAuth 2.0 client ID used for authentication. Related input keys: 'clientId', 'tokenUrl'",
      "required": false,
      "defaultValue": null
    },
    "refreshToken": {
      "type": "string",
      "sensitive": true,
      "description": "An already obtained OAuth 2.0 refresh token which will be used to get a new access token via the Refresh Token grant type. Related input keys: 'clientId', 'clientSecret', 'tokenUrl'",
      "required": false,
      "defaultValue": null
    },
    "tokenType": {
      "type": "string",
      "description": "Specifies the type of OAuth 2.0 token to use for authentication. 'ACCESS' uses an access token for authorizing the HTTP request, while 'ID' uses an ID token. Defaults to 'ACCESS'.",
      "allowedValues": [
        "ID",
        "ACCESS"
      ],
      "required": false,
      "defaultValue": "ACCESS"
    },
    "authorizationHeader": {
      "type": "string",
      "sensitive": true,
      "description": "Explicit value for the HTTP Authorization header. This overwrites all other authentication mechanisms.",
      "required": false,
      "defaultValue": null
    },
    "csrfUrl": {
      "type": "string",
      "description": "An optional CSRF URL which will be used to obtain an X-CSRF-TOKEN via a GET request",
      "required": false
    },
    "headers": {
      "type": "object",
      "description": "The request headers. The values are not sensitive. Examples: Content-Type, Accept, Authorization. If the Authorization header is provided, it will overwrite the 'user' and 'password' values.",
      "required": false
    },
    "body": {
      "type": "string",
      "description": "The payload of the HTTP request",
      "required": false
    },
    "timeout": {
      "type": "number",
      "description": "An optional execution timeout in seconds",
      "required": false,
      "minValue": 1,
      "maxValue": 90,
      "defaultValue": "3"
    },
    "succeedOnTimeout": {
      "type": "boolean",
      "description": "Prevents the command from failing in case of a timeout. If set to true, the response of the timed-out request will have body 'null', the response headers will be '{}', and the response status code will be '-1'.",
      "required": false,
      "defaultValue": "false"
    },
    "trustAnyCert": {
      "type": "boolean",
      "description": "When set to true, allows all TLS server certificates to be trusted for this HTTP request, including CSRF and token endpoints. Do not enable this in productive environments.",
      "required": false,
      "defaultValue": "false"
    },
    "trustedCerts": {
      "type": "string",
      "description": "One or more trusted server X.509 certificates. The value needs to be in PEM format, and it may optionally be Base64-encoded.",
      "required": false
    },
    "clientCert": {
      "type": "string",
      "sensitive": true,
      "description": "A client certificate which contains a private key and one or more X.509 certificates. The value needs to be in PEM format, and it may optionally be Base64-encoded.",
      "required": false,
      "defaultValue": null
    },
    "successResponseCodes": {
      "type": "array",
      "description": "The response codes which will be used to treat this HTTP request as successful. Example: [\"2xx\", \"3xx\", \"404\"]",
      "required": false,
      "defaultValue": "[\"2xx\"]"
    },
    "responseBodyTransformer": {
      "type": "string",
      "sensitive": false,
      "description": "A dynamic expression used to transform the response body string. If you need to use it as an object, it must be parsed, for example, using 'toObject'. The result replaces the original response body. Do not put the expression in the $() construct.",
      "required": false
    },
    "sccEnabled": {
      "type": "boolean",
      "sensitive": false,
      "description": "When set to true, enables the routing of HTTP requests through the SAP Cloud Connector to reach private endpoints",
      "required": false,
      "defaultValue": "false"
    },
    "routeOauthThroughScc": {
      "type": "boolean",
      "sensitive": false,
      "description": "When set to true, routes OAuth token requests through the SAP Cloud Connector. This setting does not affect routing of the main HTTP request.",
      "required": false,
      "defaultValue": "false"
    },
    "sccLocationId": {
      "type": "string",
      "sensitive": false,
      "description": "Specifies the Cloud Connector instance over which the connection should be opened in scenarios where multiple connectors are available. If not specified, the connection is opened to the Cloud Connector that is connected without any location ID.",
      "required": false
    },
    "sccTechnicalUserPropagation": {
      "type": "boolean",
      "sensitive": false,
      "description": "Enables the use of technical user propagation when making calls through the SAP Cloud Connector. You can set it to true only if 'sccEnabled' is also true, and if an OAuth authentication flow is used.",
      "required": false,
      "defaultValue": "false"
    },
    "omitBodyInErrorMessage": {
      "type": "boolean",
      "sensitive": false,
      "description": "Whether the response body should be excluded from the error message when the HTTP request fails. Set this to true if you want to avoid sensitive data exposure.",
      "required": false,
      "defaultValue": "false"
    },
    "ignoreResponseBody": {
      "type": "boolean",
      "sensitive": false,
      "description": "When set to true, the response body is omitted from the command output. Use this to avoid execution size limit failures when the response body is not needed. This setting is independent of 'omitBodyInErrorMessage'.",
      "required": false,
      "defaultValue": "false"
    }
  },
  "outputKeys": {
    "body": {
      "type": "string",
      "description": "The response payload"
    },
    "headers": {
      "type": "object",
      "description": "The response headers"
    },
    "status": {
      "type": "number",
      "description": "The status code of the response. Examples: 200, 301, 404, 503. In case of no response or a timeout, the status codes may be 0 and -1."
    },
    "size": {
      "type": "number",
      "description": "The size of the response body in bytes. Example: 1048576"
    },
    "time": {
      "type": "number",
      "description": "The execution time of the request in milliseconds. Example: 321"
    },
    "url": {
      "type": "string",
      "description": "The target URL for the request"
    },
    "method": {
      "type": "string",
      "description": "The HTTP method used for the request"
    }
  }
}

