      "isError": "$(.callMcpTool.output.status < 200 or .callMcpTool.output.status >= 300 or (.callMcpTool.output.body | toObject.error) != null or (.callMcpTool.output.body | toObject.result.isError) == true)",
      "status": "$(.callMcpTool.output.status)"
