          "body": "$({jsonrpc: \"2.0\", id: 2, method: \"tools/call\", params: {name: .execution.input.toolName, arguments: (.execution.input.arguments // {})}})",
          "timeout": "$(.execution.input.timeout)",
          "successResponseCodes": "[\"2xx\", \"4xx\", \"5xx\"]",
          "responseBodyTransformer": "if (strip | startswith(\"{\")) then toObject else (ltrimstr(\"﻿\") | gsub(\"\\r\\n?\"; \"\\n\") | split(\"\\n\\n\") | map(split(\"\\n\") | map(select(startswith(\"data:\")) | sub(\"^data: ?\"; \"\")) | join(\"\\n\") | toObject | select(.id == 2 and (has(\"method\") | not) and (has(\"result\") or has(\"error\")))) | if length == 1 then first else null end) end"
        },
        "alias": "callMcpTool",
        "description": null,
        "progressMessage": "Calling MCP tool '$(.execution.input.toolName)' via destination '$(.execution.input.destinationName)'",
        "initialDelay": null,
        "pause": null,
        "when": null,
        "validate": null,
        "autoRetry": null,
        "repeat": null,
        "errorMessages": [
          {
            "message": "MCP tools/call failed at destination '$(.execution.input.destinationName)': '$(.callMcpTool.output.body | toObject.error.message)'",
            "when": {
              "semantic": "OR",
              "conditions": [
                {
                  "semantic": "OR",
                  "cases": [
                    {
                      "expression": "$(.callMcpTool.output.body | toObject.error.message | length)",
                      "operator": "GREATER_THAN",
                      "semantic": "OR",
                      "values": [
                        "0"
                      ]
                    }
                  ]
                }
              ]
            }
          },
          {
            "message": "MCP tools/call returned an invalid response at destination '$(.execution.input.destinationName)'. Expected a matching JSON-RPC '2.0' result with content blocks or a JSON-RPC error.",
            "when": {
              "semantic": "OR",
              "conditions": [
                {
                  "semantic": "OR",
                  "cases": [
                    {
                      "expression": "$(.callMcpTool.output.status >= 200 and .callMcpTool.output.status < 300)",
                      "operator": "EQUALS",
                      "semantic": "OR",
                      "values": [
                        "true"
                      ]
                    }
                  ]
                }
              ]
            }
          }
        ],
        "dryRun": null
      }
    ],
    "listeners": [
      {
        "status": "FINISHED",
        "execute": "mcp-sapcp:CloseMcpSession:1",
        "input": {
          "destinationName": "$(.execution.input.destinationName)",
          "path": "$(.execution.input.path)",
          "sessionContext": "$(.openMcpSession.output.sessionContext | toObject)"
        },
        "when": {
          "semantic": "AND",
          "conditions": [
            {
              "semantic": "AND",
              "cases": [
                {
                  "expression": "$((.openMcpSession.output.sessionContext | toObject.sessionId // \"\" | length) > 0)",
                  "operator": "EQUALS",
                  "semantic": "OR",
                  "values": [
                    "true"
                  ]
                }
              ]
            }
          ]
        }
      },
      {
        "status": "ABORTED",
        "execute": "mcp-sapcp:CloseMcpSession:1",
        "input": {
          "destinationName": "$(.execution.input.destinationName)",
          "path": "$(.execution.input.path)",
          "sessionContext": "$(.openMcpSession.output.sessionContext | toObject)"
        },
        "when": {
          "semantic": "AND",
          "conditions": [
            {
              "semantic": "AND",
              "cases": [
                {
                  "expression": "$((.openMcpSession.output.sessionContext | toObject.sessionId // \"\" | length) > 0)",
                  "operator": "EQUALS",
                  "semantic": "OR",
                  "values": [
                    "true"
                  ]
                }
              ]
            }
          ]
        }
      }
    ]
  },
