{
  "configuration": {
    "values": [],
    "output": {},
    "executors": [
      {
        "execute": "sm-sapcp:GetServiceInstanceId:1",
        "input": {
          "displayName": "$(.execution.input.instanceId)",
          "serviceKey": "$(.execution.input.serviceKey)"
        },
        "alias": "getInstanceId",
        "progressMessage": null,
        "initialDelay": null,
        "pause": null,
        "when": {
          "semantic": "AND",
          "conditions": [
            {
              "semantic": "OR",
              "cases": [
                {
                  "expression": "$(.execution.input.instanceId | isGuid)",
                  "operator": "EQUALS",
                  "semantic": "OR",
                  "values": [
                    "false"
                  ]
                }
              ]
            }
          ]
        },
        "validate": null,
        "autoRetry": null,
        "repeat": null,
        "errorMessages": []
      },
      {
        "execute": "utils-sapcp:Void:1",
        "input": {
          "message": "$(now)"
        },
        "alias": "getStartTime",
        "progressMessage": null,
        "initialDelay": null,
        "pause": null,
        "when": null,
        "validate": null,
        "autoRetry": null,
        "repeat": null,
        "errorMessages": []
      },
      {
        "execute": "http-sapcp:HttpRequest:1",
        "input": {
          "responseBodyTransformer": "toObject |  { \"state\": .state, \"errors\": .errors }",
          "clientCert": "$(.execution.input.serviceKey.certificate + .execution.input.serviceKey.key)",
          "clientId": "$(.execution.input.serviceKey.clientid)",
          "tokenUrl": "$((if (.execution.input.serviceKey.certificate == null) and (.execution.input.serviceKey.key == null) then .execution.input.serviceKey.url else .execution.input.serviceKey.certurl end) + \"/oauth/token\")",
          "method": "GET",
          "clientSecret": "$(.execution.input.serviceKey.clientsecret)",
          "url": "$(.execution.input.serviceKey.sm_url)/v1/service_instances/$(if .execution.input.instanceId | isGuid then .execution.input.instanceId else .getInstanceId.output.instanceId end)/operations/$(.execution.input.operation)",
          "timeout": "10"
        },
        "alias": "waitSuccessfulOperation5seconds",
        "progressMessage": null,
        "initialDelay": null,
        "pause": null,
        "when": null,
        "validate": {
          "semantic": "AND",
          "conditions": [
            {
              "semantic": "AND",
              "cases": [
                {
                  "expression": "$(.waitSuccessfulOperation5seconds.output.body | toObject.state)",
                  "operator": "NOT_EQUALS",
                  "semantic": "OR",
                  "values": [
                    "failed"
                  ]
                }
              ]
            },
            {
              "semantic": "OR",
              "cases": [
                {
                  "expression": "$((.execution.input.deadline * 60) - ((now | toNumber) - (.getStartTime.output.message | toNumber)) > 0)",
                  "operator": "EQUALS",
                  "semantic": "OR",
                  "values": [
                    "true"
                  ]
                },
                {
                  "expression": "$(.waitSuccessfulOperation5seconds.output.body | toObject.state)",
                  "operator": "EQUALS",
                  "semantic": "OR",
                  "values": [
                    "succeeded"
                  ]
                }
              ]
            }
          ]
        },
        "autoRetry": {
          "maxCount": 3,
          "delay": "5s",
          "logic": "INCREMENTAL",
          "applyOnValidation": false,
          "when": {
            "semantic": "OR",
            "conditions": [
              {
                "semantic": "OR",
                "cases": [
                  {
                    "expression": "$([408, 429, 500, 502, 503, 504, -1] | filter(. == $.waitSuccessfulOperation5seconds.output.status) | length)",
                    "operator": "EQUALS",
                    "semantic": "OR",
                    "values": [
                      "1"
                    ]
                  }
                ]
              }
            ]
          }
        },
        "repeat": {
          "maxCount": 6,
          "until": {
            "semantic": "OR",
            "conditions": [
              {
                "semantic": "OR",
                "cases": [
                  {
                    "expression": "$(.waitSuccessfulOperation5seconds.output.body | toObject.state)",
                    "operator": "NOT_EQUALS",
                    "semantic": "OR",
                    "values": [
                      "never-terminal"
                    ]
                  }
                ]
              }
            ]
          },
          "delay": "5s",
          "failOnMaxCount": false
        },
        "errorMessages": [
          {
            "message": "The service instance operation did not complete successfully in $(.execution.input.deadline) minutes",
            "when": {
              "semantic": "AND",
              "conditions": [
                {
                  "semantic": "OR",
                  "cases": [
                    {
                      "expression": "$(.waitSuccessfulOperation5seconds.output.body | toObject.state)",
                      "operator": "EQUALS",
                      "semantic": "OR",
                      "values": [
                        "in progress"
                      ]
                    }
                  ]
                },
                {
                  "semantic": "OR",
                  "cases": [
                    {
                      "expression": "$((.execution.input.deadline * 60) - (now - (.getStartTime.output.message | toNumber)) <= 0)",
                      "operator": "EQUALS",
                      "semantic": "OR",
                      "values": [
                        "true"
                      ]
                    }
                  ]
                }
              ]
            }
          },
          {
            "message": "The operation failed with the following error$(if .waitSuccessfulOperation5seconds.output.body | toObject.errors | length > 1 then \"s:\\n\" else \":\" end)$(.waitSuccessfulOperation5seconds.output.body | toObject.errors | join(\"\\n\"))",
            "when": {
              "semantic": "OR",
              "conditions": [
                {
                  "semantic": "OR",
                  "cases": [
                    {
                      "expression": "$(.waitSuccessfulOperation5seconds.output.body | toObject.state)",
                      "operator": "EQUALS",
                      "semantic": "OR",
                      "values": [
                        "failed"
                      ]
                    }
                  ]
                }
              ]
            }
          }
        ]
      },
      {
        "execute": "http-sapcp:HttpRequest:1",
        "input": {
          "responseBodyTransformer": "toObject |  { \"state\": .state, \"errors\": .errors }",
